SourceCode.Declaration:
/// <summary>
/// Data contract for CPI-driven Sales Order repricing.
/// Provides parameters required for batch execution such as site, thread count,
/// process identifiers, and query definitions.
/// </summary>
[  DataContract,
   SysOperationAlwaysInitialize,
   SysOperationContractProcessing(classStr(METCPIRepricingUIBuilder))
]
class METCPIRepricingContract extends METSysOperationTaskDataContract implements SysOperationInitializable
{
    guid                 topPickingProcessId;
    str                  packedQuery;
    List                 inventSiteIdList;
    boolean              cpIFlag;


}

Method.Source:
/// <summary>
/// Gets or sets the list of InventSiteIds for the operation.
/// </summary>
/// <param name="_inventSiteIdList">
/// Optional parameter. If provided, assigns the given list of site IDs to the contract.
/// </param>
/// <returns>
/// Returns the current list of InventSiteIds associated with the contract.
/// </returns>
[DataMember,
 DataCollection(Types::String),
 SysOperationLabel("@SYS103211"),
 SysOperationDisplayOrder('3'),
 AifCollectionType('return', Types::String)]
public List parminventSiteIdList(List _inventSiteIdList = inventSiteIdList)
{
    inventSiteIdList = _inventSiteIdList;
    return inventSiteIdList;
}

/// <summary>
/// Gets or sets the number of threads to be used for batch execution.
/// Controls parallel processing efficiency during repricing.
/// </summary>
/// <param name="_threadCount">Thread count value.</param>
/// <returns>The current thread count.</returns>
[DataMember,
 SysOperationDisplayOrder('1'),
 SysOperationControlVisibilityAttribute(true)]
public METThreadCount parmThreadCount(METThreadCount _threadCount = threadCount)
{
    threadCount = _threadCount;
    return threadCount;
}

/// <summary>
/// Gets or sets the unique identifier for the top picking process.
/// Used to track and associate batch execution with a specific process instance.
/// </summary>
/// <param name="_topPickingProcessId">Process identifier (GUID).</param>
/// <returns>The current process identifier.</returns>
[DataMember,
 SysOperationDisplayOrder('2'),
 SysOperationControlVisibility(false)]
public guid parmTopPickingProcessId(guid _topPickingProcessId = topPickingProcessId)
{
    topPickingProcessId = _topPickingProcessId;
    return topPickingProcessId;
}

   /// <summary>
   /// Gets or sets the cpi flag.
   /// Used to track the Reprice process for CPI-driven repricing.
   /// </summary>
   /// <param name="_cpiFlag">CPI flag (boolean).</param>
   /// <returns>The current CPI flag.</returns>
   [DataMemberAttribute('@MET:CPIRepriced'),
SysOperationLabelAttribute("@MET:CPIRepriced")]
   public boolean parmCPIFlag(boolean _cpiFlag = cpIFlag)
   {
       cpIFlag = _cpiFlag;
       return cpIFlag;
   }

/// <summary>
/// Gets or sets the packed query string used to define Sales Order selection criteria.
/// </summary>
/// <param name="_packedQuery">Base64-encoded query string.</param>
/// <returns>The current packed query string.</returns>
[DataMemberAttribute,
 AifQueryTypeAttribute('_packedQuery', queryStr(METCPIRepricingQuery))]
public str parmPackedQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;
    return packedQuery;
}

/// <summary>
/// Decodes the packed query string and returns a Query object.
/// </summary>
/// <returns>A Query object constructed from the packed query.</returns>
public Query getQuery()
{
    return new Query(SysOperationHelper::base64Decode(packedQuery));
}

/// <summary>
/// Initializes and returns a query object for SalesTable records.
/// </summary>
/// <remarks>
/// Adds ranges to the query based on the InventSiteId list provided in the data contract.
/// This ensures that only SalesTable records matching the specified site IDs are included.
/// </remarks>
/// <returns>
/// A Query object with ranges applied for InventSiteId values.
/// </returns>
public Query initQuery()
{
    QueryBuildDataSource qbds;
    Query                query;

    void addRangesFromList(List _list, FieldId _fieldId)
    {
        ListEnumerator enum;

        enum = _list.getEnumerator() as ListEnumerator;

        while (enum && enum.moveNext())
        {
            qbds.addRange(_fieldId).value(enum.current());
        }
    }

    query = this.getQuery();
    qbds = query.dataSourceTable(tableNum(SalesTable));

    if (qbds)
    {
        addRangesFromList(inventSiteIdList, fieldNum(SalesTable, InventSiteId));
    }

    return query;
}

/// <summary>
/// Validates the parameters.
/// </summary>
/// <returns>Is validated</returns>
public boolean validate()
{
    boolean isValid = true;

    super();

    if (!inventSiteIdList.elements())
    {
        isValid = checkFailed("@MET:SiteMadatory");
    }

    return isValid;
}
